    description: "Six KVM switches compared on monitor count, 4K refresh rate, USB ports, laptop docking and remote access, with picks for two PCs, four PCs and dual monitors.",
    mainKeyword: "kvm switch Because the USB hub is shared, a printer or a drive that is connected will follow whichever computer is active, so do not start a large file copy and then switch away mid-transfer. The four-port design is popular with people who run a gaming PC, a work laptop, a mini PC and a console capture box, since a single hotkey moves the keyboard and screen to the right machine. Before you buy, check which graphics outputs each computer has, since a laptop with only one HDMI port will give a single screen to the switch no matter how many monitors are attached. For people who hot-desk with a laptop, the single-cable docking feature is the real saving, because you plug in once and get charging, monitors, network and peripherals together. Check that both your monitors support the refresh rate you want, since the switch will fall back to the slower of the two displays when they differ. Because it works below the operating system, it can be used to reinstall an operating system or change BIOS settings on a machine that is in another room or building. If a computer is asleep when you switch, it may take a moment for the picture to appear, so give it a few seconds before assuming the switch has failed. Keep the HDMI cables short and of the same type, as a long cheap cable on one input is a common reason one of four computers misbehaves. The desktop controller is worth placing within easy reach, since reaching behind the monitors for a button makes the switch much less convenient. Before relying on it, confirm that your laptop charger wattage and your laptop USB-C port both match what the dock provides, because a mismatch limits charging speed. If you use it for gaming, test the refresh rate after every switch, because some graphics drivers reset to a lower rate when a monitor reconnects. For a first setup, connect it to a spare machine and practice before using it on a server that you cannot easily reach if something goes wrong.",
